import org.osgi.service.useradmin.UserAdmin;

/**
 * Feature: the UserAdmin store component is visible through the Configuration REST API v2 only to identities holding
 * the kura.admin permission, as verified through the IdentityService, in every request that lists or returns
 * component configurations or pids.
 */
public class ConfigurationRestServiceUserStoreVisibilityTest {

    private static final String USER_STORE_PID = "org.eclipse.kura.internal.useradmin.store.RoleRepositoryStoreImpl";
    private static final String OTHER_PID = "org.eclipse.kura.clock.ClockService";

    private static final String ADMIN = "admin";
    private static final String OPERATOR = "operator";

    private final ConfigurationService configurationService = mock(ConfigurationService.class);
    private final IdentityService identityService = mock(IdentityService.class);
    private final Set<String> admins = new HashSet<>();

    private boolean identityServiceAvailable = true;
    private ConfigurationRestService service;
    private ContainerRequestContext requestContext;
    private Set<String> resultPids;

    /*
     * Scenarios
     */

    @Test
    public void adminIdentifiedByIdentityServiceSeesUserStoreConfiguration() throws KuraException {
        givenAdminIdentity(ADMIN);
        givenRequestFrom(ADMIN);
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenConfigurationsAreListed();

        thenResultPidsAre(USER_STORE_PID, OTHER_PID);
    }

    @Test
    public void adminIsTreatedAsNonAdminWhenIdentityServiceIsMissing() throws KuraException {
        givenAdminIdentity(ADMIN);
        givenRequestFrom(ADMIN);
        givenIdentityServiceMissing();
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenConfigurationsAreListed();

        thenResultPidsAre(OTHER_PID);
    }

    @Test
    public void nonAdminPidListDoesNotContainUserStore() throws KuraException {
        givenRequestFrom(OPERATOR);
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenPidsAreListed();

        thenResultPidsAre(OTHER_PID);
    }

    @Test
    public void adminPidListContainsUserStore() throws KuraException {
        givenAdminIdentity(ADMIN);
        givenRequestFrom(ADMIN);
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenPidsAreListed();

        thenResultPidsAre(USER_STORE_PID, OTHER_PID);
    }

    @Test
    public void nonAdminPidsWithFactoryDoNotContainUserStore() throws KuraException {
        givenRequestFrom(OPERATOR);
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenPidsWithFactoryAreListed();

        thenResultPidsAre(OTHER_PID);
    }

    @Test
    public void nonAdminDefaultConfigurationDoesNotContainUserStore() throws KuraException {
        givenRequestFrom(OPERATOR);
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenDefaultConfigurationsAreRequested(USER_STORE_PID, OTHER_PID);

        thenResultPidsAre(OTHER_PID);
    }

    @Test
    public void adminDefaultConfigurationContainsUserStore() throws KuraException {
        givenAdminIdentity(ADMIN);
        givenRequestFrom(ADMIN);
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenDefaultConfigurationsAreRequested(USER_STORE_PID, OTHER_PID);

        thenResultPidsAre(USER_STORE_PID, OTHER_PID);
    }

    @Test
    public void cloudRequestPidListContainsUserStore() throws KuraException {
        givenCloudRequest();
        givenComponents(USER_STORE_PID, OTHER_PID);

        whenPidsAreListed();

        thenResultPidsAre(USER_STORE_PID, OTHER_PID);
    }

    /*
     * Steps
     */

    /*
     * Given
     */

    private void givenAdminIdentity(final String name) {
        this.admins.add(name);
    }

    private void givenIdentityServiceMissing() {
        this.identityServiceAvailable = false;
    }

    private void givenRequestFrom(final String name) {
        final SecurityContext securityContext = mock(SecurityContext.class);
        when(securityContext.getUserPrincipal()).thenReturn(() -> name);
        this.requestContext = mock(ContainerRequestContext.class);
        when(this.requestContext.getSecurityContext()).thenReturn(securityContext);
    }

    private void givenCloudRequest() {
        this.requestContext = null;
    }

    private void givenComponents(final String... pids) throws KuraException {
        final List<ComponentConfiguration> configs = Arrays.stream(pids).map(this::configuration)
                .collect(Collectors.toList());
        when(this.configurationService.getComponentConfigurations()).thenReturn(configs);
        when(this.configurationService.getConfigurableComponentPids())
                .thenReturn(new HashSet<>(Arrays.asList(pids)));
        for (final String pid : pids) {
            when(this.configurationService.getDefaultComponentConfiguration(pid)).thenReturn(configuration(pid));
        }
    }

    /*
     * When
     */

    private void whenConfigurationsAreListed() {
        createService();
        this.resultPids = this.service.listComponentConfigurations(this.requestContext).getConfigs().stream()
                .map(ComponentConfigurationDTO::getPid).collect(Collectors.toSet());
    }

    private void whenPidsAreListed() {
        createService();
        this.resultPids = this.service.listConfigurableComponentsPids(this.requestContext).getPids();
    }

    private void whenPidsWithFactoryAreListed() {
        createService();
        this.resultPids = this.service.listConfigurableComponentsPidAndFactoryPid(this.requestContext).getComponents()
                .stream().map(PidAndFactoryPid::getPid).collect(Collectors.toSet());
    }

    private void whenDefaultConfigurationsAreRequested(final String... pids) {
        createService();
        this.resultPids = this.service
                .listDefaultComponentConfiguration(new PidSet(new HashSet<>(Arrays.asList(pids))), this.requestContext)
                .getConfigs().stream().map(ComponentConfigurationDTO::getPid).collect(Collectors.toSet());
    }

    /*
     * Then
     */

    private void thenResultPidsAre(final String... pids) {
        assertEquals(new HashSet<>(Arrays.asList(pids)), this.resultPids);
    }

    /*
     * Utilities
     */

    private ComponentConfiguration configuration(final String pid) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("kura.service.pid", pid);
        final Tocd definition = new Tocd();
        definition.setId(pid);
        return new ComponentConfigurationImpl(pid, definition, properties);
    }

    private void createService() {
        try {
            doAnswer(i -> {
                if (!this.admins.contains(i.getArgument(0, String.class))
                        || !"kura.admin".equals(i.getArgument(1, Permission.class).getName())) {
                    throw new KuraException(KuraErrorCode.SECURITY_EXCEPTION);
                }
                return null;
            }).when(this.identityService).checkPermission(anyString(), any());
        } catch (final KuraException e) {
            throw new IllegalStateException(e);
        }

        // the UserAdmin knows no identity: the kura.admin permission can only be verified through the IdentityService
        final UserAdmin userAdmin = mock(UserAdmin.class);
        when(userAdmin.createRole(anyString(), anyInt())).thenReturn(null);

        final EnvironmentInfo environmentInfo = mock(EnvironmentInfo.class);
        when(environmentInfo.getNonFrameworkArgs()).thenReturn(new String[0]);

        this.service = new ConfigurationRestService();
        this.service.setEnvironmentInfo(environmentInfo);
        this.service.setUserAdmin(userAdmin);
        this.service.setCryptoService(mock(CryptoService.class));
        this.service.setConfigurationService(this.configurationService);
        if (this.identityServiceAvailable) {
            this.service.setIdentityService(this.identityService);
        }
    }
}
